using LaboratoryDesktopApp.DemoData;
using LaboratoryDesktopApp.Models;
using LaboratoryDesktopApp.Theme;

namespace LaboratoryDesktopApp.Controls;

public class TestCategoriesControl : UserControl
{
    private readonly DataGridView grid=new();private readonly TextBox search=ThemeHelper.TextBox();public TestCategoriesControl(){Dock=DockStyle.Fill;ThemeHelper.StylePage(this);Padding=new Padding(26);var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));root.RowStyles.Add(new RowStyle(SizeType.Absolute,62));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));var top=new Panel{Dock=DockStyle.Fill};top.Controls.Add(new Label{Text="Test Categories",Font=AppTheme.PageTitle,AutoSize=true,Location=new Point(0,4)});var add=ThemeHelper.Button("+ Add Category",true);add.Anchor=AnchorStyles.Top|AnchorStyles.Right;top.Resize+=(_,_)=>add.Left=top.ClientSize.Width-add.Width;top.Controls.Add(add);root.Controls.Add(top,0,0);var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};search.Width=280;search.PlaceholderText="Search categories...";search.TextChanged+=(_,_)=>RefreshGrid();bar.Controls.Add(search);root.Controls.Add(bar,0,1);ThemeHelper.StyleGrid(grid);grid.Dock=DockStyle.Fill;grid.Columns.Add("Name","Category");grid.Columns.Add("Description","Description");grid.Columns.Add("Count","Linked demo tests");grid.Columns.Add("Status","Status");grid.Columns.Add("Action","Actions");grid.CellClick+=(_,e)=>{if(e.RowIndex<0)return;var c=DemoDataProvider.Categories.FirstOrDefault(x=>x.Name==Convert.ToString(grid.Rows[e.RowIndex].Cells["Name"].Value));if(c==null)return;if(e.ColumnIndex==4){var result=MessageBox.Show("Yes = edit, No = toggle active status.","Category",MessageBoxButtons.YesNoCancel);if(result==DialogResult.Yes)Edit(c);else if(result==DialogResult.No){c.IsActive=!c.IsActive;RefreshGrid();}}};root.Controls.Add(grid,0,2);Controls.Add(root);add.Click+=(_,_)=>Edit(null);RefreshGrid();}
    private void RefreshGrid(){grid.Rows.Clear();foreach(var c in DemoDataProvider.Categories.Where(c=>c.Name.Contains(search.Text,StringComparison.OrdinalIgnoreCase)))grid.Rows.Add(c.Name,c.Description,DemoDataProvider.Tests.Count(t=>t.Category==c.Name),c.IsActive?"Active":"Inactive","Edit | Toggle");}
    private void Edit(TestCategory? c){var name=Microsoft.VisualBasic.Interaction.InputBox("Category name:",c==null?"Add category":"Edit category",c?.Name??"").Trim();if(string.IsNullOrWhiteSpace(name)){if(c==null)MessageBox.Show("Category name is required.");return;}if(DemoDataProvider.Categories.Any(x=>x.Name.Equals(name,StringComparison.OrdinalIgnoreCase)&&x.Id!=c?.Id)){MessageBox.Show("Category already exists.");return;}if(c==null)DemoDataProvider.Categories.Add(new(){Name=name,Description="Demo category"});else c.Name=name;RefreshGrid();}
}
